import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"构建、签名与发版","description":"","frontmatter":{},"headers":[],"relativePath":"reference/releasing.md","filePath":"reference/releasing.md","lastUpdated":1795426969000}'),d={name:"reference/releasing.md"};function o(r,e,c,l,n,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="构建、签名与发版" tabindex="-1">构建、签名与发版 <a class="header-anchor" href="#构建、签名与发版" aria-label="Permalink to &quot;构建、签名与发版&quot;">​</a></h1><p>桌面版是 Tauri 应用，服务端、Web 产物和原生沙箱 helper 随安装包一起分发。发布分三步：构建、签名、整理产物。当前 0.3.4 只完成构建与整理，自动更新签名仍未配置。</p><h2 id="_1-构建" tabindex="-1">1. 构建 <a class="header-anchor" href="#_1-构建" aria-label="Permalink to &quot;1. 构建&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release:build</span></span></code></pre></div><p><code>scripts/build-tauri.mjs</code> 会编译 <code>apps/native/hearth-native.cs</code>（调用系统 <code>csc.exe</code>），准备内置 Node、服务端 bundle 和 Web 产物，再调用 <code>tauri build</code>，最终把 NSIS 安装包复制到仓库根目录的 <code>release/</code>。</p><p>没有签名环境变量时，脚本会打印一条警告并生成<strong>不带自动更新</strong>的普通安装包。它不会生成一个签名无效、装上就无法更新的坏包。</p><p>0.3.4 的实际产物：<code>Hearth_0.3.4_x64-setup.exe</code> 30.5 MiB、<code>Hearth-0.3.4-portable.zip</code> 47.2 MiB，已作为 GitHub Pre-release 发布并附 SHA256 校验和。</p><h2 id="_2-自动更新签名" tabindex="-1">2. 自动更新签名 <a class="header-anchor" href="#_2-自动更新签名" aria-label="Permalink to &quot;2. 自动更新签名&quot;">​</a></h2><p>自动更新需要三项一起提供：</p><table tabindex="0"><thead><tr><th>变量</th><th>用途</th></tr></thead><tbody><tr><td><code>TAURI_SIGNING_PRIVATE_KEY</code></td><td>给更新产物签名；可以是文件路径或密钥内容</td></tr><tr><td><code>HEARTH_UPDATER_PUBKEY</code></td><td>客户端内置的公钥，用来验证更新</td></tr><tr><td><code>HEARTH_UPDATER_ENDPOINT</code></td><td>客户端检查更新的 <code>latest.json</code> 地址</td></tr></tbody></table><p>三项齐全时，构建脚本会生成临时 <code>src-tauri/updater.build.json</code>，打开 <code>createUpdaterArtifacts</code> 并启用 <code>updater</code> Cargo feature，然后产出 <code>.sig</code> 文件。三项缺一，自动更新关闭。</p><p>私钥只放在发布机器或 CI secret 中，不进入仓库。公钥可以公开。</p><h2 id="_3-整理发布产物" tabindex="-1">3. 整理发布产物 <a class="header-anchor" href="#_3-整理发布产物" aria-label="Permalink to &quot;3. 整理发布产物&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release:prepare</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 或使用已有安装包，不重新构建</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release:prepare</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skip-build</span></span></code></pre></div><p>脚本会在 <code>release/&lt;version&gt;/</code> 生成：</p><ul><li><code>Hearth_&lt;version&gt;_x64-setup.exe</code>：Windows 安装包；</li><li><code>Hearth-&lt;version&gt;-portable.zip</code>：解压后保持 <code>resources/</code> 与 <code>Hearth.exe</code> 同级，直接运行；</li><li><code>RELEASE_NOTES.md</code>：版本、提交列表、安装说明；</li><li><code>SHA256SUMS.txt</code>：安装包、便携包和发布说明的校验和；</li><li><code>latest.json</code>（可选）：设置 <code>HEARTH_RELEASE_BASE_URL</code> 且有 <code>.sig</code> 时生成，供 Tauri updater 使用。</li></ul><p><code>latest.json</code> 里的下载地址由 <code>HEARTH_RELEASE_BASE_URL</code> 加安装包文件名拼成，所以要把安装包和 <code>latest.json</code> 上传到同一版本目录。</p><h2 id="发布前检查" tabindex="-1">发布前检查 <a class="header-anchor" href="#发布前检查" aria-label="Permalink to &quot;发布前检查&quot;">​</a></h2><ul><li><code>npm run version:check &amp;&amp; npm run typecheck &amp;&amp; npm test &amp;&amp; npm run test:longrun &amp;&amp; npm run build &amp;&amp; npm run docs:build</code></li><li><code>npm run test:sandbox</code>（Windows 真实 AppContainer 测试）</li><li><code>npm run first:run -- --fake</code>（离线自检任务链路）</li><li><code>cargo check --manifest-path apps/desktop-tauri/src-tauri/Cargo.toml --features updater</code></li><li>安装包在干净机器上安装、启动、卸载各一次；</li><li>下载后核对 <code>SHA256SUMS.txt</code>；</li><li>至少在一台旧版本机器上验证一次自动更新。</li></ul><p>发布脚本不会自动打 tag、推远端或上传文件。这些步骤需要人确认后执行。</p><h2 id="当前缺口" tabindex="-1">当前缺口 <a class="header-anchor" href="#当前缺口" aria-label="Permalink to &quot;当前缺口&quot;">​</a></h2><p>0.3.4 没有 <code>TAURI_SIGNING_PRIVATE_KEY</code>、<code>HEARTH_UPDATER_PUBKEY</code> 和 <code>HEARTH_UPDATER_ENDPOINT</code>，所以不会生成 <code>.sig</code> 或 <code>latest.json</code>，客户端也没有可用的更新源。Windows Authenticode、干净机卸载重装和企业策略检查同样未验收；发布前检查中的后三项仍是人工留空项。</p>`,22)])])}const k=a(d,[["render",o]]);export{u as __pageData,k as default};
